,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Fetch_Dashboard_Counts'
,p_static_id=>'fetch-dashboard-counts'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    l_total NUMBER;',
'    l_pending_tech NUMBER;',
'    l_pending_acc NUMBER;',
'    l_completed NUMBER;',
'    l_js_code VARCHAR2(32767);',
'BEGIN',
unistr('    -- 1. \062C\0644\0628 \0627\0644\0623\0631\0642\0627\0645 \0645\0646 \0627\0644\062F\0627\062A\0627\0628\064A\0632'),
'    SELECT COUNT(*) INTO l_total FROM cr_request;',
'    SELECT COUNT(*) INTO l_pending_tech FROM cr_request WHERE status_code IN (''AWAITING_TECH_REVIEW'', ''TECHNICIAN_REWORK'');',
'    SELECT COUNT(*) INTO l_pending_acc FROM cr_request WHERE status_code = ''AWAITING_ACCOUNTING'';',
'    SELECT COUNT(*) INTO l_completed FROM cr_request WHERE status_code = ''COMPLETED'';',
'',
unistr('    -- 2. \0628\0646\0627\0621 \0643\0648\062F JavaScript \0644\062A\062D\062F\064A\062B \0627\0644\0639\0646\0627\0635\0631'),
'    l_js_code := ''',
'        document.getElementById("total_req").innerHTML = "'' || l_total || ''";',
'        document.getElementById("pending_tech").innerHTML = "'' || l_pending_tech || ''";',
'        document.getElementById("pending_acc").innerHTML = "'' || l_pending_acc || ''";',
'        document.getElementById("completed").innerHTML = "'' || l_completed || ''";',
'    '';',
'',
unistr('    -- 3. \0625\0636\0627\0641\0629 \0627\0644\0643\0648\062F \0639\0634\0627\0646 \064A\062A\0646\0641\0630 \0628\0639\062F \062A\062D\0645\064A\0644 \0627\0644\0635\0641\062D\0629'),
'    APEX_JAVASCRIPT.ADD_ONLOAD_CODE(l_js_code);',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>7418283140332109116
,p_created_on=>wwv_flow_imp.dz('20261024085039Z')
,p_updated_on=>wwv_flow_imp.dz('20261024085039Z')
,p_created_by=>'OMRNOUR99@OUTLOOK.COM'
,p_updated_by=>'OMRNOUR99@OUTLOOK.COM'
);
end;
